import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.DOB-AMqW.js";const u=JSON.parse('{"title":"Personix Support","description":"Official support information for Personix.","frontmatter":{"title":"Personix Support","description":"Official support information for Personix.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"support/personix.md","filePath":"support/personix.md"}'),s={name:"support/personix.md"};function i(n,e,l,p,c,d){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="personix-support" tabindex="-1">Personix Support <a class="header-anchor" href="#personix-support" aria-label="Permalink to &quot;Personix Support&quot;">​</a></h1><p>For Personix support, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p><p>Include the Personix version, Android or browser version, device model, a description of the issue, and safe reproduction steps when possible.</p><p>Do not email medical records, personal identifiers, contact details, app PINs, backup passwords, or <code>.pxbackup</code> files.</p><h2 id="common-help" tabindex="-1">Common help <a class="header-anchor" href="#common-help" aria-label="Permalink to &quot;Common help&quot;">​</a></h2><ul><li><strong>Forgotten app PIN:</strong> Personix does not store a recoverable PIN. Clearing app storage or reinstalling also removes local data, so preserve a usable encrypted backup beforehand.</li><li><strong>Biometric unlock unavailable:</strong> unlock with the app PIN and confirm that Android has an enrolled supported biometric.</li><li><strong>Backup restore fails:</strong> select a valid Personix <code>.pxbackup</code> file and enter the exact backup password used to create it.</li><li><strong>Preview metadata is missing:</strong> confirm internet access and the relevant metadata setting. Browser metadata fetching remains off until you explicitly enable it.</li></ul>',6)])])}const m=o(s,[["render",i]]);export{u as __pageData,m as default};
